use httpreq::{RequestBuilder, HttpRequest};

#[test]
fn test_basic_get() {
    let req: HttpRequest = RequestBuilder::new()
        .method("GET")
        .url("https://example.com")
        .build();
    assert_eq!(req.method, "GET");
    assert_eq!(req.url, "https://example.com");
    assert!(req.body.is_none());
}

#[test]
fn test_post_with_body() {
    let req = RequestBuilder::new()
        .method("POST")
        .url("https://api.example.com/data")
        .body("hello world")
        .build();
    assert_eq!(req.method, "POST");
    assert_eq!(req.body, Some("hello world".to_string()));
}

#[test]
fn test_add_header() {
    let req = RequestBuilder::new()
        .method("GET")
        .url("https://example.com")
        .header("Authorization", "Bearer token123")
        .build();
    assert_eq!(req.headers.get("Authorization").map(|s| s.as_str()), Some("Bearer token123"));
}

#[test]
fn test_multiple_headers() {
    let req = RequestBuilder::new()
        .method("GET")
        .url("https://example.com")
        .header("Accept", "application/json")
        .header("X-Custom", "value")
        .build();
    assert_eq!(req.headers.len(), 2);
}

#[test]
fn test_chaining_returns_builder() {
    // Verify the builder methods return Self for chaining
    let req = RequestBuilder::new()
        .method("DELETE")
        .url("https://example.com/resource/1")
        .header("Accept", "*/*")
        .build();
    assert_eq!(req.method, "DELETE");
    assert_eq!(req.headers.len(), 1);
}

