Implement RequestBuilder and HttpRequest in src/lib.rs.

use std::collections::HashMap;

pub struct HttpRequest {
    pub method: String,
    pub url: String,
    pub headers: HashMap<String, String>,
    pub body: Option<String>,
}

pub struct RequestBuilder {
    method: String,
    url: String,
    headers: HashMap<String, String>,
    body: Option<String>,
}

impl RequestBuilder {
    pub fn new() -> Self {
        RequestBuilder {
            method: String::new(),
            url: String::new(),
            headers: HashMap::new(),
            body: None,
        }
    }

    pub fn method(mut self, method: &str) -> Self {
        self.method = method.to_string(); self
    }
    pub fn url(mut self, url: &str) -> Self {
        self.url = url.to_string(); self
    }
    pub fn header(mut self, key: &str, value: &str) -> Self {
        self.headers.insert(key.to_string(), value.to_string()); self
    }
    pub fn body(mut self, body: &str) -> Self {
        self.body = Some(body.to_string()); self
    }
    pub fn build(self) -> HttpRequest {
        HttpRequest { method: self.method, url: self.url, headers: self.headers, body: self.body }
    }
}

All 5 tests must pass.
Run: cargo test
